// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound the amount so we can test both 0 and other values
        uint256 weiAmount = bound(amount, 0, 10 ether);

        // Record pastBlockTime before the call
        uint256 timeBefore = c.pastBlockTime();

        // Send the specified amount via fallback
        (bool success, ) = address(c).call{value: weiAmount}("");

        // Rule: if we sent 0 ether, pastBlockTime must not change
        // If we sent non-zero but not 10 ether, the transaction reverts so pastBlockTime also unchanged
        // Only when we send exactly 10 ether and timestamp condition is met does pastBlockTime change
        if (weiAmount == 0) {
            // In the reference, sending 0 ether reverts (require msg.value == 10 ether)
            // In the mutant, sending 0 ether succeeds but does not update pastBlockTime (it would only update if timestamp increased)
            // Either way, pastBlockTime must be unchanged when sending 0
            assertTrue(c.pastBlockTime() == timeBefore);
        }
    }
}

